syntax:
struct StructName {
    member_type member_name;
    ...
};

// No constructors, no initializers, all members are public, no inheritance

code_example:
struct Data {
    int ival;
    char s[20];
};

// Initialization using designated initializers in C99
struct Data data_instance = { .ival = 42, .s = "example" };

// Direct access to members without encapsulation
data_instance.ival = 100;
strcpy(data_instance.s, "updated");
